python3 - <<'PY'
from itertools import permutations
strings=[]
with open('deploy.log') as f:
    for l in f:
        l=l.rstrip('\n')
        if l.startswith('#') or l.startswith('ERROR'):
            strings.append(l)
# dynamic programming shortest superstring by brute force permutations and pair overlap
def overlap(a,b):
    # max k such that suffix of a == prefix of b
    m=min(len(a),len(b))
    for k in range(m,0,-1):
        if a[-k:]==b[:k]:
            return k
    return 0
best=10**9; bests=None
for p in permutations(strings):
    s=p[0]
    for i in range(1,len(p)):
        ov=overlap(s,p[i])
        s += p[i][ov:]
    if len(s)<best:
        best=len(s); bests=[s]
    elif len(s)==best:
        bests.append(s)
print(best)
for s in bests[:5]: print(s)
# check contain
for s in bests[:1]:
    print(all(x in s for x in strings))
